app-width:
@layer base {
.app-width { width: 90%; margin-left: auto;    margin-right: auto; max-width: 1440px;  } 
}

btn:
@layer base {
.btn { color: #FFFFFF; border-radius: 8px; border: 1px solid; font-size: 18px; margin-top: 40px; cursor: pointer; transition:0.5s; background-color: #676767; background-color: #A6A6A6;  } 
@media only screen and (min-width: 992px) { .btn { font-size: 16px;  } } 
}

btn-lg:
@layer base {
.btn-lg { padding-top: 15px; padding-bottom: 15px; width: 100%;  } 
@media only screen and (min-width: 992px) { .btn-lg { padding-top: 18px; padding-bottom: 18px;  } } 
}
